package geometry

import (
	"encoding/json"
	"os"
	"strconv"
	"testing"
)

// These expectations are the approved contract, shared with Rust, rather than outputs
// generated by Scalar or Admit. Geometry integers stay exact across JSON consumers.
func TestSharedVectors(t *testing.T) {
	b, err := os.ReadFile("../../meta/testdata/geometry-v1.json")
	if err != nil {
		t.Fatal(err)
	}
	var f struct {
		Version int `json:"version"`
		Cases   []struct {
			ID       string `json:"id"`
			Size     string `json:"size_bytes"`
			Chunk    string `json:"chunk_bytes"`
			Count    string `json:"chunks"`
			Replicas uint32 `json:"replicas"`
			MinISR   uint32 `json:"min_isr"`
			Scalar   bool   `json:"scalar_ok"`
			Admit    bool   `json:"admission_ok"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	if f.Version != 1 || len(f.Cases) < 35 {
		t.Fatal("incomplete vector contract")
	}
	for _, v := range f.Cases {
		t.Run(v.ID, func(t *testing.T) {
			parse := func(s string) uint64 {
				n, e := strconv.ParseUint(s, 10, 64)
				if e != nil {
					t.Fatal(e)
				}
				return n
			}
			size, chunk, want := parse(v.Size), parse(v.Chunk), parse(v.Count)
			n, e := Scalar(size, chunk)
			if (e == nil) != v.Scalar || n != want {
				t.Fatalf("Scalar = %d,%v; want %d, accepted=%t", n, e, want, v.Scalar)
			}
			n, e = Admit(size, chunk, v.Replicas, v.MinISR)
			if (e == nil) != v.Admit || e == nil && n != want {
				t.Fatalf("Admit = %d,%v; want %d, accepted=%t", n, e, want, v.Admit)
			}
		})
	}
}

func TestMetadataBoundInputs(t *testing.T) {
	for _, x := range []struct {
		n uint64
		r uint32
	}{{0, 1}, {65537, 1}, {^uint64(0), 5}, {1, 0}, {1, 6}, {65536, ^uint32(0)}} {
		if _, err := MetadataBound(x.n, x.r); err == nil {
			t.Errorf("accepted count=%d RF=%d", x.n, x.r)
		}
	}
	for _, x := range []struct {
		n     uint64
		r     uint32
		bound uint64
	}{{5137, 1, 4193840}, {3881, 2, 4193528}, {3119, 3, 4193984}, {2607, 4, 4194104}, {2239, 5, 4193456}} {
		b, e := MetadataBound(x.n, x.r)
		if e != nil || b != x.bound {
			t.Errorf("bound N=%d R=%d: %d,%v want %d", x.n, x.r, b, e, x.bound)
		}
	}
}
